import pyarrow.parquet as pq
tr=pq.read_table('data/AgentWorldModel-1K/verl/train.parquet').to_pandas()
te=pq.read_table('data/AgentWorldModel-1K/verl/test.parquet').to_pandas()
def norm(p):
    return ' '.join(str(m.get('content','')) if isinstance(m,dict) else str(m) for m in list(p))
trp={}
for i,p in enumerate(tr['prompt']):
    trp.setdefault(norm(p),[]).append(i)
ovl=0; ex=None
for i,p in enumerate(te['prompt']):
    n=norm(p)
    if n in trp:
        ovl+=1
        if ex is None: ex=(i, trp[n][0])
print('full-prompt overlap:', ovl, '/', len(te))
if ex:
    i,j=ex
    print('test row:', dict(te.iloc[i]['env_kwargs']))
    print('train row:', dict(tr.iloc[j]['env_kwargs']))
